solutionCode:
#[derive(Debug, PartialEq)]
pub enum Sol {
    Pleno,
    Nublado,
    Escuro,
}

pub fn a_resposta_do_mato(sol: Sol) -> String {
    match sol {
        Sol::Pleno => String::from("cresce"),
        Sol::Nublado => String::from("sobrevive"),
        Sol::Escuro => String::from("murcha"),
    }
}

testsCode:
use desafio::a_resposta_do_mato;
use desafio::Sol;

#[test]
fn testa_a_resposta_ao_sol_pleno() {
    assert_eq!(a_resposta_do_mato(Sol::Pleno), String::from("cresce"));
}

#[test]
fn testa_a_resposta_ao_sol_nublado() {
    assert_eq!(a_resposta_do_mato(Sol::Nublado), String::from("sobrevive"));
}

#[test]
fn testa_a_resposta_ao_sol_escuro() {
    assert_eq!(a_resposta_do_mato(Sol::Escuro), String::from("murcha"));
}
